})", "ai_justification": "Stale KB articles cause Now Assist to surface outdated solutions to agents and end users. AI Search ranks articles by relevance but cannot determine accuracy -- fresh content directly improves AI response quality.", "remediation_guidance": "Establish a KB governance process with mandatory annual review cycles. Use the KB article review queue to identify and update or retire stale articles. Target: ≤20% of published articles over 12 months old.", "is_manual": "0", "is_clone_sensitive": "0", "sys_name": "KB Article Age and Staleness" }, { "module": "ITSM", "check_name": "KB Article Retirement Rate", "order": "30", "check_script": "(function(checkDef, dateFilter) {
 var gaRetired = new GlideAggregate('kb_knowledge');
 gaRetired.addQuery('workflow_state', 'retired');
 gaRetired.addAggregate('COUNT');
 gaRetired.query();
 var retired = gaRetired.next() ? parseInt(gaRetired.getAggregate('COUNT')) : 0;

 var gaTotal = new GlideAggregate('kb_knowledge');
 gaTotal.addAggregate('COUNT');
 gaTotal.query();
 var total = gaTotal.next() ? parseInt(gaTotal.getAggregate('COUNT')) : 0;

 var pct = total > 0 ? Math.round((retired / total) * 100) : 0;
 var actualValue = pct + '% retired (' + retired + ' of ' + total + ' articles)';

 // Informational check — active retirement indicates good KB hygiene
 return {
