})", "ai_justification": "Device metrics provide the granular CPU, memory, disk, and network signals that DEX AI uses for root cause analysis. Without sufficient metric coverage, AI diagnosis will misattribute or miss the actual cause of endpoint issues.", "remediation_guidance": "Assign labels to published KB articles. Create a label taxonomy aligned to your product/service catalog. Labels allow Now Assist AI Search to filter results by audience and service context.", "is_manual": "0", "is_clone_sensitive": "0", "sys_name": "KB Article Label Coverage" }, { "module": "ITSM", "check_name": "KB Articles with Raw URLs in Body", "order": "80", "check_script": "(function(checkDef, dateFilter) {
 var gaTotal = new GlideAggregate('kb_knowledge');
 gaTotal.addQuery('workflow_state', 'published');
 gaTotal.addQuery('active', true);
 gaTotal.addAggregate('COUNT');
 gaTotal.query();
 var total = gaTotal.next() ? parseInt(gaTotal.getAggregate('COUNT')) : 0;

 if (total === 0) {
 return {
 status: 'not_applicable',
 actualValue: 'No published KB articles found',
 finding: 'No published KB articles found. URL content check cannot be assessed.'
 };
 }

 var gaURL = new GlideAggregate('kb_knowledge');
 gaURL.addQuery('workflow_state', 'published');
 gaURL.addQuery('active', true);
 gaURL.addQuery('text', 'CONTAINS', 'https://');
 gaURL.addAggregate('COUNT');
 gaURL.query();
 var withUrl = gaURL.next() ? parseInt(gaURL.getAggregate('COUNT')) : 0;

 var pct = Math.round((withUrl / total) * 100);
 var actualValue = withUrl + ' of ' + total + ' published articles contain raw URLs (' + pct + '%)';

 if (pct <= 20) {
 return {
 status: 'ready',
 actualValue: actualValue,
 finding: 'Only ' + pct + '% of articles contain raw URLs. Now Assist AI Search has predominantly self-contained content that can be summarized without link dependencies.'
 };
 } else if (pct <= 50) {
 return {
 status: 'needs_attention',
 actualValue: actualValue,
 finding: pct + '% of published articles contain raw URLs (target: ≤20%). Now Assist cannot follow hyperlinks — URL-dependent content will produce incomplete AI summaries.'
 };
 } else {
 return {
 status: 'not_ready',
 actualValue: actualValue,
 finding: pct + '% of published articles rely on raw URLs. Now Assist AI Search cannot follow links — the majority of KB content will produce incomplete AI summaries and poor self-service answers.'
 };
 }
})", "ai_justification": "Application health data enables DEX AI to diagnose app-specific issues such as Zoom quality and Office 365 performance. Without application monitoring, DEX AI diagnosis is limited to OS-level signals only.", "remediation_guidance": "Replace URL-dependent content with inline text — summarize what the link contains directly in the article body. Now Assist cannot follow hyperlinks. Target: ≤20% of published articles containing raw URLs.", "is_manual": "0", "is_clone_sensitive": "0", "sys_name": "KB Articles with Raw URLs in Body" }, { "module": "ITSM", "check_name": "KB Article AI Content Suitability", "order": "90", "check_script": "(function(checkDef, dateFilter) {
 var gaTables = new GlideAggregate('kb_knowledge');
